    /**
     * Handles loading a Site using a UUID
     * @param		UUID uuid 
     * @return		Site
     */    
    @GetMapping("/load")
    public Site load( @RequestParam(required=true) UUID uuid ) {    	
    	Site entity = null;

    	try {  
    		entity = service.getSite( new SiteFetchOneSummary( uuid ) );   
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING, "failed to load Site using Id " + uuid );
            return null;
        }

        return entity;
    }

